<?php
namespace App\Http\Controllers;
use App\Models\{InventoryLocation,InventoryMovement,SupplyBatch,SupplyCategory,SupplyItem,UnitOfMeasurement};
use App\Services\InventoryService;
use Illuminate\Http\{RedirectResponse,Request};
use Illuminate\View\View;
class AISMSController extends Controller {
 private function authz(Request $r,string $action='view'):void { abort_unless($r->user()->canModuleAction('aisms',$action),403); }
  public function index(Request $r):View {$this->authz($r);$items=SupplyItem::with(['category','unit'])->withSum('batches as stock','quantity_available')->when($r->string('search')->toString(),fn($q,$s)=>$q->where('name','like','%'.$s.'%')->orWhere('code','like','%'.$s.'%'))->paginate(15)->withQueryString();$allItems=SupplyItem::where('status','active')->orderBy('name')->get();$batches=SupplyBatch::with(['item','location'])->where('quantity_available','>',0)->latest()->get();$lowStock=0;$totalStock=(float)$batches->sum('quantity_available');$expiring=SupplyBatch::with('item')->where('quantity_available','>',0)->whereBetween('expires_on',[now()->toDateString(),now()->addDays(30)->toDateString()])->get();$expired=SupplyBatch::with('item')->where('quantity_available','>',0)->whereDate('expires_on','<',now())->get();$movements=InventoryMovement::with(['batch.item','batch.location','user'])->latest()->paginate(15,['*'],'movements_page');$itemOptions=$allItems->map(fn($i)=>'<option value='.$i->id.'>'.e($i->code.' — '.$i->name).'</option>')->implode('');$locationOptions=InventoryLocation::where('is_active',true)->get()->map(fn($l)=>'<option value='.$l->id.'>'.e($l->name).'</option>')->implode('');$batchOptions=$batches->map(fn($b)=>'<option value='.$b->id.'>'.e($b->item->name.' — '.$b->batch_number.' ('.$b->quantity_available.')').'</option>')->implode('');return view('modules.aisms.dashboard',['header'=>'Agricultural Inventory & Supply Management System','description'=>'Manage agricultural supply inventory and stock transactions','items'=>$items,'itemsForForms'=>$allItems,'batches'=>$batches,'lowStock'=>$lowStock,'totalStock'=>$totalStock,'expiring'=>$expiring,'expired'=>$expired,'categories'=>SupplyCategory::where('is_active',true)->get(),'units'=>UnitOfMeasurement::all(),'locations'=>InventoryLocation::where('is_active',true)->get(),'movements'=>$movements,'itemOptions'=>$itemOptions,'locationOptions'=>$locationOptions,'batchOptions'=>$batchOptions,'canCreate'=>$r->user()->canModuleAction('aisms','create'),'canReceive'=>$r->user()->canModuleAction('aisms','receive'),'canRelease'=>$r->user()->canModuleAction('aisms','release'),'canAdjust'=>$r->user()->canModuleAction('aisms','adjust'),'canExport'=>$r->user()->canModuleAction('aisms','export')]);}
 public function item(Request $r):RedirectResponse {$this->authz($r,'create');$d=$r->validate(['category_id'=>'required|exists:supply_categories,id','unit_id'=>'required|exists:units_of_measurement,id','code'=>'required|max:50','name'=>'required|max:150','minimum_stock'=>'required|numeric|min:0']);SupplyItem::create($d+['status'=>'active']);return back()->with('status','Supply item registered.');}
 public function receive(Request $r,InventoryService $s):RedirectResponse {$this->authz($r,'receive');$d=$r->validate(['supply_item_id'=>'required|exists:supply_items,id','location_id'=>'required|exists:inventory_locations,id','batch_number'=>'required|max:100','received_on'=>'required|date','expires_on'=>'nullable|date|after_or_equal:received_on','quantity'=>'required|numeric|min:0.01','notes'=>'nullable|max:1000']);$s->receive($d,$r->user()->id);return back()->with('status','Stock receipt posted.');}
 public function adjust(Request $r,InventoryService $s):RedirectResponse {$this->authz($r,'adjust');$d=$r->validate(['supply_batch_id'=>'required|exists:supply_batches,id','quantity'=>'required|numeric|not_in:0','adjustment_reason'=>'required|string|max:500','notes'=>'nullable|max:1000']);$s->adjust($d,$r->user()->id);return back()->with('status','Stock adjustment posted.');}
 public function release(Request $r,InventoryService $s):RedirectResponse {$this->authz($r,'release');$d=$r->validate(['supply_batch_id'=>'required|exists:supply_batches,id','quantity'=>'required|numeric|min:0.01','recipient'=>'required|max:150','purpose'=>'required|max:255','notes'=>'nullable|max:1000']);$s->release($d,$r->user()->id);return back()->with('status','Stock release posted.');}
 public function export(Request $r) { $this->authz($r,'reports');$rows=InventoryMovement::with('batch.item')->latest()->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['Reference','Type','Item','Quantity','Date']);foreach($rows as $m)fputcsv($out,[$m->reference,$m->movement_type,$m->batch->item->name,$m->quantity,$m->created_at]);fclose($out);},'aisms-movements.csv',['Content-Type'=>'text/csv']); }
}
